steps.script:
(() => {
  // A. **신규 run(도구 실측 있음) = 정확 경로.** 이 대화는 수정 배포(07755e05) 이후에 돌아
  //    도구 step 이 `result_summary.elapsed_ms` 를 갖는다. 추론 단계는 자기 소요를 갖고,
  //    도구는 자기 실행분만 갖는다 — 초판은 정확히 그 반대였다(추론 +0.0초 / 도구 +11초).
  try { localStorage.setItem('web.stepSidePanel.width', '340'); } catch (e) {}
  const btn = document.querySelector('.bubble-steps-btn');
  if (!btn) throw new Error('PB0008 FAIL: 단계 보기 버튼 없음');
  btn.click();
  const items = [...document.querySelectorAll('.step-side-panel-item')];
  if (!items.length) throw new Error('PB0008 FAIL: 단계 0');
  const rows = items.map((it) => {
    const t = it.querySelector('.step-side-panel-time');
    const badge = it.querySelector('.step-tool-badge');
    const seg = t ? t.textContent.split(' · ') : [];
    return {
      isTool: !!badge,
      text: t ? t.textContent : '',
      title: t ? t.title : '',
      self: seg.length > 1 && !/^누적 /.test(seg[1]) ? seg[1] : null,
      cum: (seg.find((s) => /^누적 /.test(s)) || '').replace('누적 ', '') || null,
    };
  });
  const secs = (s) => {
    if (!s) return NaN;
    const m = /^~?(?:(\d+)분 )?(\d+(?:\.\d)?)초$/.exec(s);
    return m ? parseInt(m[1] || '0', 10) * 60 + parseFloat(m[2]) : NaN;
  };
  const tools = rows.filter((r) => r.isTool);
  const acts = rows.filter((r) => !r.isTool);
  const cums = rows.map((r) => secs(r.cum)).filter((v) => Number.isFinite(v));
  const m = {
    steps: rows.length,
    tools: tools.length,
    // 신규 run 이므로 도구는 전부 실측 → 소요가 있고 근사 표식이 없어야 한다.
    toolsWithSelf: tools.filter((r) => r.self).length,
    toolsApprox: tools.filter((r) => r.self && r.self.startsWith('~')).length,
    toolsUnderOneSec: tools.filter((r) => secs(r.self) < 3).length,
    // 추론 단계 중 최소 하나는 실제 추론 시간(>= 5초)을 자기 소요로 가져야 한다.
    actsWithSelf: acts.filter((r) => r.self).length,
    maxActSelf: Math.max(...acts.map((r) => secs(r.self)).filter((v) => Number.isFinite(v)), 0),
    anyApprox: rows.some((r) => r.self && r.self.startsWith('~')),
    anyPlusPrefix: rows.some((r) => r.text.includes('+')),
    cumMonotonic: cums.every((v, i) => i === 0 || v >= cums[i - 1]),
    firstHasNoCum: !rows[0].cum,
    lastSelf: rows[rows.length - 1].self,
    sample: rows.slice(0, 6).map((r) => (r.isTool ? '[도구] ' : '[내부] ') + r.text),
  };
  const bad = [];
  if (!m.tools) bad.push('도구 단계 0 — 이 대화로는 정확 경로를 볼 수 없다');
  if (m.toolsWithSelf !== m.tools) bad.push('도구 소요 누락 ' + m.toolsWithSelf + '/' + m.tools);
  if (m.toolsApprox !== 0) bad.push('신규 run 인데 도구에 근사 표식 ' + m.toolsApprox);
  if (m.toolsUnderOneSec !== m.tools) bad.push('도구 소요가 추론 시간을 흡수한 흔적(3초 이상)');
  if (m.maxActSelf < 5) bad.push('추론 단계가 자기 소요를 못 가짐(max=' + m.maxActSelf + '초)');
  if (m.anyApprox) bad.push('신규 run 에 근사 표식 존재');
  if (m.anyPlusPrefix) bad.push("'+' 간격 접두 잔재");
  if (!m.cumMonotonic) bad.push('누적 비단조 ' + JSON.stringify(cums));
  if (!m.firstHasNoCum) bad.push('첫 단계에 누적 중복 표기');
  if (bad.length) throw new Error('PB0008 ASSERT FAIL A(정확 경로) ' + JSON.stringify(bad));
  return JSON.stringify(m);
})()

(() => {
  // 확대 캡처 — 패널이 뷰포트의 340px 조각이라 10.5px 표기를 전체화면 캡처로는 읽을 수 없다.
  //   라이브 패널 DOM 을 **복제**해 2.2× 로 얹는다(재렌더가 아니라 복제 → 픽셀 동일).
  window.__pbZoom = (label) => {
    document.querySelectorAll('#pb-steptiming-zoom').forEach((n) => n.remove());
    const panel = document.getElementById('stepSidePanel');
    const host = document.createElement('div');
    host.id = 'pb-steptiming-zoom';
    host.setAttribute('data-marker', 'steptiming2-pb0008-ef1f438a');
    host.style.cssText = 'position:fixed;inset:0;z-index:2147483647;background:#fff;overflow:auto';
    const hd = document.createElement('div');
    hd.style.cssText = 'font:600 13px/1.5 system-ui;padding:10px 20px;border-bottom:1px solid #e5e9f0;color:#26251e';
    hd.textContent = 'PB-0008 · 단계 시간 귀속 (라이브 패널 DOM 복제 2.2× 확대) · ' + label + ' · marker=steptiming2-pb0008-ef1f438a';
    host.appendChild(hd);
    const stage = document.createElement('div');
    stage.style.cssText = 'transform:scale(2.2);transform-origin:top left;width:' + Math.round(panel.getBoundingClientRect().width) + 'px';
    const clone = panel.cloneNode(true);
    clone.removeAttribute('id');
    clone.style.cssText = 'position:static;width:100%;height:auto;max-height:none;box-shadow:none;border:1px solid #e5e9f0';
    const body = clone.querySelector('#stepSidePanelBody');
    if (body) { body.style.maxHeight = 'none'; body.style.overflow = 'visible'; }
    stage.appendChild(clone);
    host.appendChild(stage);
    // ⚠️ **실제로 문서에 붙여야 캡처에 나온다.** 초판은 이 줄이 없어 detached 노드를 세고
    //    있었고(개수는 맞게 나온다) 스크린샷에는 오버레이가 아예 없었다 — 캡처가 근거가
    //    되지 못했다. 아래 반환값도 '문서에 붙은 뒤' 세도록 순서를 지킨다.
    document.body.appendChild(host);
    if (!document.getElementById('pb-steptiming-zoom')) throw new Error('PB0008 FAIL: 확대 오버레이 미부착');
    return document.querySelectorAll('#pb-steptiming-zoom .step-side-panel-time').length;
  };
  const n = window.__pbZoom('신규 run — 도구 실측 있음(정확)');
  if (!n) throw new Error('PB0008 FAIL: 확대 복제에 시간 표기 0');
  return JSON.stringify({ zoomedTimes: n });
})()

(() => {
  // B. **과거 대화(도구 실측 없음) = 정직한 폴백.** 분리 불가능한 구간의 숫자를 비운다.
  const btn = document.querySelector('.bubble-steps-btn');
  if (!btn) throw new Error('PB0008 FAIL: 단계 보기 버튼 없음');
  btn.click();
  const items = [...document.querySelectorAll('.step-side-panel-item')];
  const rows = items.map((it) => {
    const t = it.querySelector('.step-side-panel-time');
    const seg = t ? t.textContent.split(' · ') : [];
    return {
      isTool: !!it.querySelector('.step-tool-badge'),
      text: t ? t.textContent : '',
      title: t ? t.title : '',
      self: seg.length > 1 && !/^누적 /.test(seg[1]) ? seg[1] : null,
    };
  });
  // 추론(내부) 직후의 첫 도구 = 소요를 알 수 없는 자리. 그 자리가 **비어 있어야** 한다.
  let firstToolAfterAct = -1;
  for (let i = 1; i < rows.length; i++) {
    if (rows[i].isTool && !rows[i - 1].isTool) { firstToolAfterAct = i; break; }
  }
  const m = {
    steps: rows.length,
    firstToolAfterActIdx: firstToolAfterAct,
    firstToolAfterActSelf: firstToolAfterAct >= 0 ? rows[firstToolAfterAct].self : null,
    firstToolAfterActTitle: firstToolAfterAct >= 0 ? rows[firstToolAfterAct].title : '',
    approxCount: rows.filter((r) => r.self && r.self.startsWith('~')).length,
    anyPlusPrefix: rows.some((r) => r.text.includes('+')),
    sample: rows.slice(0, 6).map((r) => (r.isTool ? '[도구] ' : '[내부] ') + r.text),
  };
  const bad = [];
  if (firstToolAfterAct < 0) bad.push('추론 직후 도구가 없는 대화 — 폴백 축을 볼 수 없다');
  if (m.firstToolAfterActSelf !== null) {
    bad.push('분리 불가능한 자리에 숫자를 지어냄: ' + m.firstToolAfterActSelf);
  }
  if (!/분리할 수 없어/.test(m.firstToolAfterActTitle)) bad.push('사유 툴팁 없음');
  if (m.approxCount === 0) bad.push('과거 대화인데 근사 표식(~) 0 — 정확한 척하고 있다');
  if (m.anyPlusPrefix) bad.push("'+' 간격 접두 잔재");
  if (bad.length) throw new Error('PB0008 ASSERT FAIL B(폴백) ' + JSON.stringify(bad));
  return JSON.stringify(m);
})()

