    if (!document.getElementById('pb-steptiming-zoom')) throw new Error('PB0008 FAIL: 확대 오버레이 미부착');
    return document.querySelectorAll('#pb-steptiming-zoom .step-side-panel-time').length;
  };
  const n = window.__pbZoom('과거 대화 — 도구 실측 없음(모르는 칸은 비운다)');
  if (!n) throw new Error('PB0008 FAIL: 확대 복제에 시간 표기 0');
  // 폴백의 핵심 자리(추론 ~11초 → 도구 소요 비움)가 캡처 안에 보이도록 맞춘다.
  const host = document.getElementById('pb-steptiming-zoom');
  const it3 = host.querySelectorAll('.step-side-panel-item')[2];
  if (it3) host.scrollTop = Math.max(0, it3.getBoundingClientRect().top - host.getBoundingClientRect().top + host.scrollTop - 40);
  return JSON.stringify({ zoomedTimes: n });
})()
